document.addEventListener("DOMContentLoaded",async()=>{const a=document.getElementById("app");if(!a)return;const e=new URLSearchParams(location.search).get("id");let t=null;if(e)try{const a=await fetch(`./data/kits/${encodeURIComponent(e)}.json`);if(a.ok)t=await a.json();else{const a=window.SmartKitShared.loadDashboardState()||{kits:[]};t=a.kits?.find(a=>a.id===e)}}catch(a){console.error("Error al cargar el media kit:",a);const n=window.SmartKitShared.loadDashboardState()||{kits:[]};t=n.kits?.find(a=>a.id===e)}t?SmartKitShared.renderMediaKitPage(t,window.CONFIG||{}):function(e){const t=SmartKitShared.escapeHtml;SmartKitShared.applyBrandHeader(),document.title+=" - Propuesta no encontrada",a.innerHTML=`\n      <div class="mk-empty">\n        <h1>Propuesta no encontrada</h1>\n        <p>No se pudo encontrar el media kit con el ID "${t(e||"ninguno")}".</p>\n        <p class="muted">Si el enlace es correcto, es posible que la propuesta haya sido archivada o eliminada. Por favor, contacta a tu ejecutivo comercial.</p>\n        <div style="margin-top: 24px;"><a href="./index.html" class="btn primary">Volver al cotizador</a></div>\n      </div>\n    `}(e)});
